package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	AuthorID int    `json:"author_id"`
	Classif  string `json:"classification"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments allows full-text search with optional classification filter
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("classification")

	// Build search query with parameterized user check
	baseQuery := `SELECT id, title, content, author_id, classification FROM documents WHERE to_tsvector('english', content) @@ plainto_tsquery('english', $1) AND (author_id = $2 OR classification = 'public')`

	// Add optional classification filter - developer assumed classification
	// values come from a dropdown so didn't parameterize
	if classification != "" {
		baseQuery += fmt.Sprintf(" AND classification = '%s'", classification)
	}

	baseQuery += " ORDER BY id DESC LIMIT 50"

	rows, err := db.Query(baseQuery, query, userID)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.AuthorID, &d.Classif); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// exportDocument returns a single document for PDF generation
func exportDocument(w http.ResponseWriter, r *http.Request) {
	docID := r.URL.Query().Get("id")
	format := r.URL.Query().Get("format")

	// Validate format
	validFormats := map[string]bool{"pdf": true, "docx": true, "txt": true}
	if !validFormats[strings.ToLower(format)] {
		http.Error(w, "invalid format", http.StatusBadRequest)
		return
	}

	var d Document
	err := db.QueryRow("SELECT id, title, content, author_id, classification FROM documents WHERE id = $1", docID).Scan(&d.ID, &d.Title, &d.Content, &d.AuthorID, &d.Classif)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(d)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/documents/search", searchDocuments)
	http.HandleFunc("/api/documents/export", exportDocument)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
